const initialState = { fields: [] };

function formReducer(state, action) {
  switch (action.type) {
    case 'ADD_FIELD':
      return { ...state, fields: [...state.fields, action.payload] };
    case 'UPDATE_FIELD':
      return {
        ...state,
        fields: state.fields.map(f =>
          f.id === action.payload.id ? { ...f, ...action.payload } : f
        )
      };
    case 'TOGGLE_REQUIRED':
      return {
        ...state,
        fields: state.fields.map(f =>
          f.id === action.payload ? { ...f, required: !f.required } : f
        )
      };
    case 'MOVE_FIELD':
      const fields = [...state.fields];
      const [moved] = fields.splice(action.payload.fromIndex, 1);
      fields.splice(action.payload.toIndex, 0, moved);
      return { ...state, fields };
    default:
      return state;
  }
}

// TenantContext controls active tenant
const TenantContext = createContext(null);

// FormEditorContext holds the per-tenant form state
const FormEditorContext = createContext(null);

function FormEditorProvider({ children }) {
  const { tenantId } = useContext(TenantContext);
  const [state, dispatch] = useReducer(formReducer, initialState);

  // Reset state when tenant changes
  useEffect(() => {
    dispatch({ type: 'RESET' });
  }, [tenantId]);

  const validate = useCallback((fields) => {
    return fields.map(field => {
      const errors = [];
      if (field.required && !field.label) errors.push('Label is required');
      if (field.type === 'number') {
        if (field.min !== undefined && field.max !== undefined && field.min > field.max) {
          errors.push('Min cannot exceed max');
        }
      }
      return { fieldId: field.id, errors, isValid: errors.length === 0 };
    });
  }, []);

  return (
    <FormEditorContext.Provider value={{ state, dispatch, validate }}>
      {children}
    </FormEditorContext.Provider>
  );
}
